import { describe, it, expect, vi } from "vitest";
import { H3, serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

// Acceptance tests for sdd/prd.md (RF-01 to RF-10) and sdd/techspec.md (D-01 to D-08).

const BODY = "0123456789";
const META: StaticAssetMeta = {
  type: "text/plain",
  etag: '"abc"',
  // Sub-second part on purpose: `last-modified` and If-Range dates must use whole seconds.
  mtime: 1_700_000_000_123,
  size: 10,
};
const LAST_MODIFIED = new Date(1_700_000_000_000).toUTCString();

describeMatrix("serve static range", (t, { it, expect }) => {
  // Mounts serveStatic on every path. Call once per test.
  function serve(overrides: Partial<ServeStaticOptions> = {}) {
    const options: ServeStaticOptions = {
      getContents: () => BODY,
      getMeta: (id) => (id === "/file.txt" ? META : undefined),
      encodings: { gzip: ".gz" },
      ...overrides,
    };
    t.app.all("/**", (event) => serveStatic(event, options));
  }

  // `accept-encoding: identity` keeps the default variant selection stable across runtimes.
  function get(path: string, headers: Record<string, string> = {}) {
    return t.fetch(path, {
      headers: { "accept-encoding": "identity", ...headers },
    });
  }

  function head(path: string, headers: Record<string, string> = {}) {
    return t.fetch(path, {
      method: "HEAD",
      headers: { "accept-encoding": "identity", ...headers },
    });
