        expect(res.status).toBe(416);
        expect(res.headers.get("content-range")).toBe("bytes */10");
        expect(res.headers.get("content-length")).toBe("0");
        expect(await res.text()).toBe("");
        expect(getContents).not.toHaveBeenCalled();
      });
    }

    it("keeps vary, etag and accept-ranges on 416", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=10-20" });
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(res.headers.get("etag")).toBe('"abc"');
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("keeps vary on 206", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.headers.get("vary")).toBe("accept-encoding");
    });
  });

  describe("RF-05: malformed or multiple ranges are ignored", () => {
    for (const range of ["bytes=abc", "items=0-1", "bytes=5-2", "bytes=0-1,4-5", "bytes=-"]) {
      it(`ignores ${range} and serves the full file with 200`, async () => {
        serve();
        const res = await get("/file.txt", { range });
        expect(res.status).toBe(200);
        expect(res.headers.get("content-range")).toBeNull();
        expect(await res.text()).toBe(BODY);
      });
    }
  });

  describe("RF-06: If-Range", () => {
    it("applies the range when If-Range is the current strong ETag", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": '"abc"' });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });

    it("ignores the range when If-Range is a different ETag", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": '"other"' });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(await res.text()).toBe(BODY);
    });

    it("ignores the range when If-Range is a weak ETag", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": 'W/"abc"' });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
    });

    it("applies the range when If-Range is the exact Last-Modified date", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": LAST_MODIFIED });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });

    it("ignores the range when If-Range is a different date", async () => {
      serve();
      const other = new Date(1_700_000_000_000 - 1000).toUTCString();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": other });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
    });

    it("answers 416 when If-Range matches and the range is unsatisfiable", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=10-20", "if-range": '"abc"' });
      expect(res.status).toBe(416);
    });

    it("ignores the range when the asset has neither ETag nor mtime", async () => {
      serve({ getMeta: () => ({ type: "text/plain", size: 10 }) });
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": '"abc"' });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
    });
  });

  describe("RF-07: conditionals run before Range", () => {
    it("returns 304 for If-None-Match with a Range header", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-none-match": '"abc"' });
      expect(res.status).toBe(304);
      expect(res.headers.get("content-range")).toBeNull();
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("returns 304 for If-Modified-Since with a Range header", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-modified-since": LAST_MODIFIED });
      expect(res.status).toBe(304);
      expect(res.headers.get("content-range")).toBeNull();
    });

    it("returns 416 instead of 304 is never produced for a matching If-None-Match", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=10-20", "if-none-match": '"abc"' });
      expect(res.status).toBe(304);
    });
  });

  describe("RF-08: range applies to the served variant", () => {
    it("uses the size of the precompressed variant and keeps its encoding headers", async () => {
      const getMeta = vi.fn((id: string): StaticAssetMeta | undefined => {
        if (id === "/app.js.gz") {
          return { type: "text/javascript", encoding: "gzip", size: 20 };
        }
        if (id === "/app.js") {
          return { type: "text/javascript", size: 10 };
        }
        return undefined;
      });
      const getContents = vi.fn((id: string) => (id === "/app.js.gz" ? "g".repeat(20) : BODY));
      serve({ getMeta, getContents });

      const res = await t.fetch("/app.js", {
        headers: { "accept-encoding": "gzip", range: "bytes=0-4" },
      });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 0-4/20");
      expect(res.headers.get("content-length")).toBe("5");
      expect(res.headers.get("content-encoding")).toBe("gzip");
      expect(res.headers.get("content-type")).toBe("text/javascript");
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(await res.text()).toBe("ggggg");
      expect(getContents).toHaveBeenCalledWith("/app.js.gz");
    });
  });

  describe("RF-09: unknown size means no range", () => {
    it("ignores Range when getMeta has no size", async () => {
      serve({
        getMeta: (id) => (id === "/file.txt" ? { type: "text/plain", etag: '"abc"' } : undefined),
      });
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(await res.text()).toBe(BODY);
    });

    it("ignores Range when size is 0 (D-08, P3)", async () => {
      serve({
        getMeta: (id) => (id === "/file.txt" ? { type: "text/plain", size: 0 } : undefined),
        getContents: () => "",
      });
      const res = await get("/file.txt", { range: "bytes=0-0" });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
    });
  });

  describe("RF-10: existing behavior is preserved", () => {
    it("serves the same 200 response without Range", async () => {
      serve();
      const res = await get("/file.txt");
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(res.headers.get("content-length")).toBe("10");
      expect(res.headers.get("etag")).toBe('"abc"');
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(await res.text()).toBe(BODY);
    });

    it("returns 404 for a missing asset even with a Range header", async () => {
      serve();
      const res = await get("/missing.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(404);
    });

    it("returns 405 with allow for POST even with a Range header", async () => {
      serve();
      const res = await t.fetch("/file.txt", {
        method: "POST",
        headers: { range: "bytes=2-5" },
      });
      expect(res.status).toBe(405);
      expect(res.headers.get("allow")).toBe("GET, HEAD");
    });
  });
});

describe("serve static range with fallthrough", () => {
  function createApp() {
    const app = new H3();
    const options: ServeStaticOptions = {
      getContents: () => BODY,
      getMeta: (id) => (id === "/file.txt" ? META : undefined),
      fallthrough: true,
    };
    app.use((event) => serveStatic(event, options));
    app.use(() => ({ fallthroughTest: "passing" }));
    return app;
  }

  it("falls through for a missing asset with Range", async () => {
    const res = await createApp().request("/missing.txt", {
      headers: { range: "bytes=2-5" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("falls through for POST with Range", async () => {
    const res = await createApp().request("/file.txt", {
      method: "POST",
      headers: { range: "bytes=2-5" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("still serves a satisfiable range", async () => {
    const res = await createApp().request("/file.txt", {
      headers: { range: "bytes=2-5" },
    });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });
