import { describe, it, expect, vi } from "vitest";
import { H3, serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

// Acceptance tests for sdd/prd.md (RF-01 to RF-10) and sdd/techspec.md (D-01 to D-08).

const BODY = "0123456789";
const META: StaticAssetMeta = {
  type: "text/plain",
  etag: '"abc"',
  // Sub-second part on purpose: `last-modified` and If-Range dates must use whole seconds.
  mtime: 1_700_000_000_123,
  size: 10,
};
const LAST_MODIFIED = new Date(1_700_000_000_000).toUTCString();

describeMatrix("serve static range", (t, { it, expect }) => {
  // Mounts serveStatic on every path. Call once per test.
  function serve(overrides: Partial<ServeStaticOptions> = {}) {
    const options: ServeStaticOptions = {
      getContents: () => BODY,
      getMeta: (id) => (id === "/file.txt" ? META : undefined),
      encodings: { gzip: ".gz" },
      ...overrides,
    };
    t.app.all("/**", (event) => serveStatic(event, options));
  }

  // `accept-encoding: identity` keeps the default variant selection stable across runtimes.
  function get(path: string, headers: Record<string, string> = {}) {
    return t.fetch(path, {
      headers: { "accept-encoding": "identity", ...headers },
    });
  }

  function head(path: string, headers: Record<string, string> = {}) {
    return t.fetch(path, {
      method: "HEAD",
      headers: { "accept-encoding": "identity", ...headers },
    });
  }

  describe("RF-01: accept-ranges", () => {
    it("advertises accept-ranges on GET without Range", async () => {
      serve();
      const res = await get("/file.txt");
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("advertises accept-ranges on GET with Range", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("advertises accept-ranges on HEAD", async () => {
      serve();
      const res = await head("/file.txt");
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("omits accept-ranges when size is unknown", async () => {
      serve({ getMeta: () => ({ type: "text/plain" }) });
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBeNull();
    });

    it("omits accept-ranges when size is 0", async () => {
      serve({ getMeta: () => ({ type: "text/plain", size: 0 }) });
      const res = await get("/file.txt");
      expect(res.headers.get("accept-ranges")).toBeNull();
    });
  });

  describe("RF-02: 206 for a satisfiable range", () => {
    it("serves bytes=2-5 as 206 with content-range, content-length and the slice", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
      expect(res.headers.get("content-length")).toBe("4");
      expect(await res.text()).toBe("2345");
    });

    it("serves an open-ended range until the end of the file", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-9/10");
      expect(await res.text()).toBe("23456789");
    });

    it("serves a suffix range with the last n bytes", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=-3" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 7-9/10");
      expect(res.headers.get("content-length")).toBe("3");
      expect(await res.text()).toBe("789");
    });

    it("serves the whole file when the suffix is larger than the file", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=-99" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 0-9/10");
      expect(res.headers.get("content-length")).toBe("10");
      expect(await res.text()).toBe(BODY);
    });

    it("limits the last byte to size - 1", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=5-99" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 5-9/10");
      expect(await res.text()).toBe("56789");
    });

    it("accepts the unit case-insensitively", async () => {
      serve();
      const res = await get("/file.txt", { range: "BYTES=2-5" });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });
  });

  describe("RF-03: HEAD with range", () => {
    it("returns 206 headers without a body and does not call getContents", async () => {
      const getContents = vi.fn(() => BODY);
      serve({ getContents });
      const res = await head("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
      expect(res.headers.get("content-length")).toBe("4");
      expect(await res.text()).toBe("");
      expect(getContents).not.toHaveBeenCalled();
    });
  });

  describe("RF-04: 416 for an unsatisfiable range", () => {
    for (const range of ["bytes=10-20", "bytes=10-", "bytes=-0"]) {
      it(`answers ${range} with 416 and no body`, async () => {
        const getContents = vi.fn(() => BODY);
        serve({ getContents });
        const res = await get("/file.txt", { range });
        expect(res.status).toBe(416);
        expect(res.headers.get("content-range")).toBe("bytes */10");
