import { beforeEach, describe, vi } from "vitest";
import { serveStatic, type ServeStaticOptions, type StaticAssetMeta } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

// Acceptance tests for sdd/prd.md (RF-01 to RF-10) and sdd/techspec.md (D-01 to D-08).

const BODY = "0123456789";
const META: StaticAssetMeta = {
  type: "text/plain",
  etag: '"abc"',
  // Sub-second part on purpose: `last-modified` and If-Range dates must use whole seconds.
  mtime: 1_700_000_000_123,
  size: 10,
};
const LAST_MODIFIED = new Date(1_700_000_000_000).toUTCString();

describeMatrix("serve static range", (t, { it, expect }) => {
  // Mounts serveStatic on every path. Call once per test.
  function serve(overrides: Partial<ServeStaticOptions> = {}) {
    const options: ServeStaticOptions = {
      getContents: () => BODY,
      getMeta: (id) => (id === "/file.txt" ? META : undefined),
      encodings: { gzip: ".gz" },
      ...overrides,
    };
    t.app.all("/**", (event) => serveStatic(event, options));
  }

  // `accept-encoding: identity` keeps the default variant selection stable across runtimes.
  function get(path: string, headers: Record<string, string> = {}) {
    return t.fetch(path, {
      headers: { "accept-encoding": "identity", ...headers },
    });
  }

  function head(path: string, headers: Record<string, string> = {}) {
    return t.fetch(path, {
      method: "HEAD",
      headers: { "accept-encoding": "identity", ...headers },
    });
  }

  describe("RF-01: accept-ranges", () => {
    it("advertises accept-ranges on GET without Range", async () => {
      serve();
      const res = await get("/file.txt");
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("advertises accept-ranges on GET with Range", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("advertises accept-ranges on HEAD", async () => {
      serve();
      const res = await head("/file.txt");
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("omits accept-ranges when size is unknown", async () => {
      serve({ getMeta: () => ({ type: "text/plain" }) });
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(200);
      expect(res.headers.get("accept-ranges")).toBeNull();
    });

    it("omits accept-ranges when size is 0", async () => {
      serve({ getMeta: () => ({ type: "text/plain", size: 0 }) });
      const res = await get("/file.txt");
      expect(res.headers.get("accept-ranges")).toBeNull();
    });
  });

  describe("RF-02: 206 for a satisfiable range", () => {
    it("serves bytes=2-5 as 206 with content-range, content-length and the slice", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
      expect(res.headers.get("content-length")).toBe("4");
      expect(await res.text()).toBe("2345");
    });

    it("serves an open-ended range until the end of the file", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-9/10");
      expect(await res.text()).toBe("23456789");
    });

    it("serves a suffix range with the last n bytes", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=-3" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 7-9/10");
      expect(res.headers.get("content-length")).toBe("3");
      expect(await res.text()).toBe("789");
    });

    it("serves the whole file when the suffix is larger than the file", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=-99" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 0-9/10");
      expect(res.headers.get("content-length")).toBe("10");
      expect(await res.text()).toBe(BODY);
    });

    it("limits the last byte to size - 1", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=5-99" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 5-9/10");
      expect(await res.text()).toBe("56789");
    });

    it("accepts the unit case-insensitively", async () => {
      serve();
      const res = await get("/file.txt", { range: "BYTES=2-5" });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });
  });

  describe("RF-03: HEAD with range", () => {
    it("returns 206 headers without a body and does not call getContents", async () => {
      const getContents = vi.fn(() => BODY);
      serve({ getContents });
      const res = await head("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 2-5/10");
      expect(res.headers.get("content-length")).toBe("4");
      expect(await res.text()).toBe("");
      expect(getContents).not.toHaveBeenCalled();
    });
  });

  describe("RF-04: 416 for an unsatisfiable range", () => {
    for (const range of ["bytes=10-20", "bytes=10-", "bytes=-0"]) {
      it(`answers ${range} with 416 and no body`, async () => {
        const getContents = vi.fn(() => BODY);
        serve({ getContents });
        const res = await get("/file.txt", { range });
        expect(res.status).toBe(416);
        expect(res.headers.get("content-range")).toBe("bytes */10");
        expect(res.headers.get("content-length")).toBe("0");
        expect(await res.text()).toBe("");
        expect(getContents).not.toHaveBeenCalled();
      });
    }

    it("keeps vary, etag and accept-ranges on 416", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=10-20" });
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(res.headers.get("etag")).toBe('"abc"');
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("keeps vary on 206", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.headers.get("vary")).toBe("accept-encoding");
    });
  });

  describe("RF-05: malformed or multiple ranges are ignored", () => {
    for (const range of ["bytes=abc", "items=0-1", "bytes=5-2", "bytes=0-1,4-5", "bytes=-"]) {
      it(`ignores ${range} and serves the full file with 200`, async () => {
        serve();
        const res = await get("/file.txt", { range });
        expect(res.status).toBe(200);
        expect(res.headers.get("content-range")).toBeNull();
        expect(await res.text()).toBe(BODY);
      });
    }
  });

  describe("RF-06: If-Range", () => {
    it("applies the range when If-Range is the current strong ETag", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": '"abc"' });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });

    it("ignores the range when If-Range is a different ETag", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": '"other"' });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(await res.text()).toBe(BODY);
    });

    it("ignores the range when If-Range is a weak ETag", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": 'W/"abc"' });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
    });

    it("applies the range when If-Range is the exact Last-Modified date", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": LAST_MODIFIED });
      expect(res.status).toBe(206);
      expect(await res.text()).toBe("2345");
    });

    it("ignores the range when If-Range is a different date", async () => {
      serve();
      const other = new Date(1_700_000_000_000 - 1000).toUTCString();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": other });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
    });

    it("answers 416 when If-Range matches and the range is unsatisfiable", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=10-20", "if-range": '"abc"' });
      expect(res.status).toBe(416);
    });

    it("ignores the range when the asset has neither ETag nor mtime", async () => {
      serve({ getMeta: () => ({ type: "text/plain", size: 10 }) });
      const res = await get("/file.txt", { range: "bytes=2-5", "if-range": '"abc"' });
      expect(res.status).toBe(200);
      expect(await res.text()).toBe(BODY);
    });
  });

  describe("RF-07: conditionals run before Range", () => {
    it("returns 304 for If-None-Match with a Range header", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-none-match": '"abc"' });
      expect(res.status).toBe(304);
      expect(res.headers.get("content-range")).toBeNull();
      expect(res.headers.get("accept-ranges")).toBe("bytes");
    });

    it("returns 304 for If-Modified-Since with a Range header", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=2-5", "if-modified-since": LAST_MODIFIED });
      expect(res.status).toBe(304);
      expect(res.headers.get("content-range")).toBeNull();
    });

    it("returns 304, not 416, for a matching If-None-Match with an unsatisfiable range", async () => {
      serve();
      const res = await get("/file.txt", { range: "bytes=10-20", "if-none-match": '"abc"' });
      expect(res.status).toBe(304);
    });
  });

  describe("RF-08: range applies to the served variant", () => {
    it("uses the size of the precompressed variant and keeps its encoding headers", async () => {
      const getMeta = vi.fn((id: string): StaticAssetMeta | undefined => {
        if (id === "/app.js.gz") {
          return { type: "text/javascript", encoding: "gzip", size: 20 };
        }
        if (id === "/app.js") {
          return { type: "text/javascript", size: 10 };
        }
        return undefined;
      });
      const getContents = vi.fn((id: string) => (id === "/app.js.gz" ? "g".repeat(20) : BODY));
      serve({ getMeta, getContents });

      const res = await t.fetch("/app.js", {
        headers: { "accept-encoding": "gzip", range: "bytes=0-4" },
      });
      expect(res.status).toBe(206);
      expect(res.headers.get("content-range")).toBe("bytes 0-4/20");
      expect(res.headers.get("content-length")).toBe("5");
      expect(res.headers.get("content-encoding")).toBe("gzip");
      expect(res.headers.get("content-type")).toBe("text/javascript");
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(await res.text()).toBe("ggggg");
      expect(getContents).toHaveBeenCalledWith("/app.js.gz");
    });
  });

  describe("RF-09: unknown size means no range", () => {
    it("ignores Range when getMeta has no size", async () => {
      serve({
        getMeta: (id) => (id === "/file.txt" ? { type: "text/plain", etag: '"abc"' } : undefined),
      });
      const res = await get("/file.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(await res.text()).toBe(BODY);
    });

    it("ignores Range when size is 0 (D-08, P3)", async () => {
      serve({
        getMeta: (id) => (id === "/file.txt" ? { type: "text/plain", size: 0 } : undefined),
        getContents: () => "",
      });
      const res = await get("/file.txt", { range: "bytes=0-0" });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
    });
  });

  describe("RF-10: existing behavior is preserved", () => {
    it("serves the same 200 response without Range", async () => {
      serve();
      const res = await get("/file.txt");
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(res.headers.get("content-length")).toBe("10");
      expect(res.headers.get("etag")).toBe('"abc"');
      expect(res.headers.get("vary")).toBe("accept-encoding");
      expect(await res.text()).toBe(BODY);
    });

    it("returns 404 for a missing asset even with a Range header", async () => {
      serve();
      const res = await get("/missing.txt", { range: "bytes=2-5" });
      expect(res.status).toBe(404);
    });

    it("returns 405 with allow for POST even with a Range header", async () => {
      serve();
      const res = await t.fetch("/file.txt", {
        method: "POST",
        headers: { range: "bytes=2-5" },
      });
      expect(res.status).toBe(405);
      expect(res.headers.get("allow")).toBe("GET, HEAD");
    });
  });
});

describeMatrix("serve static range with fallthrough", (t, { it, expect }) => {
  beforeEach(() => {
    const options: ServeStaticOptions = {
      getContents: () => BODY,
      getMeta: (id) => (id === "/file.txt" ? META : undefined),
      fallthrough: true,
    };
    t.app.use((event) => serveStatic(event, options));
    t.app.use(() => ({ fallthroughTest: "passing" }));
  });

  it("falls through for a missing asset with Range", async () => {
    const res = await t.fetch("/missing.txt", { headers: { range: "bytes=2-5" } });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("falls through for POST with Range", async () => {
    const res = await t.fetch("/file.txt", {
      method: "POST",
      headers: { range: "bytes=2-5" },
    });
    expect(await res.json()).toEqual({ fallthroughTest: "passing" });
  });

  it("still serves a satisfiable range", async () => {
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });
});

describeMatrix("serve static range body types", (t, { it, expect }) => {
  function serveBody(contents: () => BodyInit | null | undefined, size: number) {
    const options: ServeStaticOptions = {
      getContents: contents,
      getMeta: () => ({ type: "text/plain", etag: '"abc"', size }),
    };
    t.app.all("/**", (event) => serveStatic(event, options));
  }

  it("slices a string by UTF-8 bytes, not characters", async () => {
    // "a" (1 byte) + "é" (2 bytes) + "b" (1 byte) = 4 bytes.
    serveBody(() => "aéb", 4);
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=1-2" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 1-2/4");
    expect(await res.text()).toBe("é");
  });

  it("slices a Blob", async () => {
    serveBody(() => new Blob([BODY]), 10);
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });

  it("slices an ArrayBuffer", async () => {
    serveBody(() => new TextEncoder().encode(BODY).buffer as ArrayBuffer, 10);
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });

  it("respects byteOffset of a Uint8Array view", async () => {
    // The view starts at byte 2 of the underlying buffer, so the body is "0123456789".
    const buffer = new TextEncoder().encode(`XX${BODY}`);
    serveBody(() => buffer.subarray(2), 10);
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(await res.text()).toBe("2345");
  });

  it("slices a ReadableStream whose chunk boundary falls inside the range", async () => {
    // Range starts in the middle of the first chunk and ends in the second.
    serveBody(
      () =>
        new ReadableStream({
          start(controller) {
            controller.enqueue(new TextEncoder().encode("0123"));
            controller.enqueue(new TextEncoder().encode("456789"));
            controller.close();
          },
        }),
      10,
    );
    const res = await t.fetch("/file.txt", { headers: { range: "bytes=2-5" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("4");
    expect(await res.text()).toBe("2345");
  });
});

